-- Seed data for `hosts`

(7, 'Charlotte Green', '藝文解說員', '我是倫敦的藝文解說員，長期關注泰特美術館、國家美術館與西區劇場的展演動態。我擅長把藝術家的背景、作品細節與時代氛圍連結起來，讓沒有藝術基礎的旅人也能自在參與。希望透過我的分享，讓你在倫敦看展和看戲時多一層理解與感動。', '/images/hosts/host-7.jpg'),
(8, 'Élodie Laurent', '藝文解說員', '我是巴黎在地藝文解說員，喜歡從繪畫、建築、時尚與電影認識城市文化。無論是羅浮宮裡的經典作品，還是左岸小型藝廊的新銳創作，我都會用故事化方式分享。我的目標是讓旅人不必害怕藝術名詞，也能用自己的感受和巴黎產生真實連結。', '/images/hosts/host-8.jpg'),
(9, 'Hannah Keller', '藝文解說員', '我住在慕尼黑，專注於德國藝術史、古典音樂與當代設計文化。從博物館區的名作到音樂廳裡的演出傳統，我喜歡協助旅人找到適合自己的觀看方法。解說時不會只背年代與名字，而是邀請大家透過作品理解創作者的選擇與這座城市的文化性格。', '/images/hosts/host-9.jpg'),
(10, 'Noor de Vries', '藝文解說員', '我是阿姆斯特丹的藝文解說員，熟悉荷蘭黃金時代繪畫、攝影展覽與獨立設計品牌。這座城市的藝術往往和日常生活很接近，我希望帶旅人用更輕鬆的眼光看待畫作與創作。除了作品本身，也會分享博物館周邊街區、咖啡館與在地文化觀察。', '/images/hosts/host-10.jpg'),
(11, 'Beatrice Romano', '藝文解說員', '我在威尼斯從事藝術教育工作，熟悉雙年展、玻璃工藝、歌劇與文藝復興繪畫。威尼斯不只有古老宮殿，也是不斷產生新創作的城市。我會依旅人的興趣調整解說節奏，讓大家在欣賞名作與當代展覽時，都能找到屬於自己的觀點與旅行記憶。', '/images/hosts/host-11.jpg'),
(12, 'Laia Ferrer', '藝文解說員', '我是巴塞隆納的藝文解說員，關注高第建築、加泰隆尼亞現代主義與城市公共藝術。我的講解會從建築線條、色彩與生活背景切入，不讓內容變成艱深課本。希望陪旅人用更細緻的角度走進巴塞隆納，看見設計如何影響居民生活與城市氣氛。', '/images/hosts/host-12.jpg'),

(13, 'James Carter', '私廚料理人', '我是倫敦私廚料理人，擅長把英式傳統料理與現代歐洲風味結合。我的餐桌重視季節食材、料理背後的來源與大家一起分享食物的氣氛。體驗中不只會教做菜，也會介紹倫敦市場文化與食材挑選方法，讓旅人用味覺認識這座多元而充滿創意的城市。', '/images/hosts/host-13.jpg'),
(14, 'Juliette Martin', '私廚料理人', '我是在巴黎工作的私廚料理人，專長是法式家常菜、醬汁技巧與甜點搭配。我相信精緻料理不一定遙遠，關鍵在於對食材與細節的理解。課程會帶大家從市場食材開始認識巴黎飲食文化，最後一起完成一桌溫暖料理，感受法國人重視共餐與交流的日常。', '/images/hosts/host-14.jpg'),
(15, 'Maximilian Braun', '私廚料理人', '我是慕尼黑私廚料理人，喜歡研究巴伐利亞家庭料理、啤酒搭配與傳統市場食材。除了香腸與豬腳，慕尼黑還有很多細緻又溫暖的家常味道。我會帶旅人親手完成幾道經典菜色，並分享德國人如何在餐桌上聊天、慶祝與傳承家庭記憶。', '/images/hosts/host-15.jpg'),
(16, 'Femke Jansen', '私廚料理人', '我是阿姆斯特丹的私廚料理人，擅長運用當季蔬菜、起司與海鮮做出輕盈的荷蘭風味料理。我的課程重視自在與實作，不需要廚藝基礎也能享受下廚樂趣。我會分享市場採買習慣與餐桌文化，讓旅人從一頓飯裡認識阿姆斯特丹的開放與生活感。', '/images/hosts/host-16.jpg'),
(17, 'Lorenzo Bianchi', '私廚料理人', '我住在威尼斯，從家庭餐桌學會義大利料理，也熟悉潟湖海鮮與北義麵食的特色。我的私廚體驗會帶大家理解簡單食材如何靠時間、火候與耐心變得迷人。除了做菜，我也會分享威尼斯市場、漁獲與節慶飲食故事，讓旅行不只停留在觀光名單上。', '/images/hosts/host-17.jpg'),
(18, 'Mireia Costa', '私廚料理人', '我是巴塞隆納私廚料理人，專長是加泰隆尼亞海鮮料理、小盤菜與在地葡萄酒搭配。我喜歡用料理說明地中海生活方式：新鮮、分享、自在而熱情。體驗會安排簡單好上手的步驟，也會介紹市場常見食材，讓旅人把巴塞隆納明亮又有活力的味道帶回家。', '/images/hosts/host-18.jpg'),

(19, 'George Wilson', '戶外活動領隊', '我是倫敦戶外活動領隊，熟悉泰晤士河步道、皇家公園與城市單車路線。即使在繁忙都市裡，也能找到適合放慢腳步、接近綠意的旅行方式。我會依天氣與團員狀況調整節奏，並分享安全觀念與在地自然故事，讓大家安心探索倫敦不同於市中心的另一面。', '/images/hosts/host-19.jpg'),
(20, 'Théo Bernard', '戶外活動領隊', '我是巴黎戶外活動領隊，喜歡帶旅人從塞納河畔、公園步道與近郊綠地重新認識城市。我的活動不追求速度或挑戰，而是讓大家在安全舒適的節奏裡感受風景。途中會分享巴黎城市規劃、季節植物與居民休閒方式，適合想暫時離開人潮的旅人。', '/images/hosts/host-20.jpg'),
(21, 'Felix Wagner', '戶外活動領隊', '我在慕尼黑帶領戶外活動多年，熟悉英國花園、伊薩爾河岸與周邊自然路線。巴伐利亞人很重視戶外生活，我希望把這種自在感帶給每位參加者。行程中會注意安全、補水與天候變化，也會分享當地人週末如何運動、野餐與親近山林。', '/images/hosts/host-21.jpg'),
(22, 'Jasper Bakker', '戶外活動領隊', '我是阿姆斯特丹在地戶外活動領隊，最熟悉單車路線、森林公園與運河周邊的慢遊方式。這座城市平坦開闊，非常適合用身體感受街區變化。我會先說明騎乘安全與交通習慣，再帶大家走進觀光客較少注意的綠地與社區，體驗真正的荷蘭日常節奏。', '/images/hosts/host-22.jpg'),
(23, 'Matteo Ricci', '戶外活動領隊', '我是威尼斯戶外活動領隊，熟悉潟湖島嶼、海岸步道與適合慢遊的自然景觀。很多人以為威尼斯只有廣場與運河，其實周邊有豐富的水鳥、鹽田與漁村文化。我會安排安全平穩的活動節奏，帶旅人從另一個角度認識這座與水共生的城市。', '/images/hosts/host-23.jpg'),
(24, 'Arnau Puig', '戶外活動領隊', '我出生於巴塞隆納，長期帶領城市健走、海岸步道與近郊自然活動。這裡同時擁有海灘、山丘和充滿活力的街區，非常適合喜歡移動旅行的人。我會依團員體力調整路線，並分享防曬、補水與安全建議，讓大家用自在方式感受地中海城市的能量。', '/images/hosts/host-24.jpg'),

(25, 'Emily Parker', '旅拍攝影師', '我是倫敦旅拍攝影師，擅長利用自然光、街景與人物互動留下有故事感的照片。比起制式擺拍，我更喜歡捕捉旅人走過紅色電話亭、河岸與市場時的真實表情。拍攝前會先了解你的期待與風格，過程中也會提供簡單引導，讓不習慣面對鏡頭的人也能放鬆享受。', '/images/hosts/host-25.jpg'),
(26, 'Manon Lefèvre', '旅拍攝影師', '我是在巴黎工作的旅拍攝影師，喜歡用柔和光線與街道層次記錄人物和城市的關係。從清晨的咖啡館外到黃昏的塞納河畔，每個時間都有不同氛圍。我會安排自然、不趕時間的拍攝節奏，並協助旅人找到適合自己的角度，留下比觀光紀念照更有情感的畫面。', '/images/hosts/host-26.jpg'),
(27, 'Sven Hoffmann', '旅拍攝影師', '我是慕尼黑旅拍攝影師，擅長城市建築、人像與節慶現場紀錄。慕尼黑有整齊的街景、溫暖的啤酒花園與充滿生活感的市場，我喜歡把這些元素放進照片裡。拍攝時會以自然互動為主，並分享構圖小技巧，讓旅人不但得到照片，也能學會觀察城市的方式。', '/images/hosts/host-27.jpg'),
(28, 'Lotte Smit', '旅拍攝影師', '我是阿姆斯特丹旅拍攝影師，喜歡拍攝運河倒影、單車生活與人物在街區散步的瞬間。這座城市的光線常常隨天氣變化，因此每次拍攝都有不同驚喜。我會帶你走進適合取景的小橋、花市與住宅區，用輕鬆聊天的方式完成一組自然又有旅行感的人像照片。', '/images/hosts/host-28.jpg'),
(29, 'Chiara Bellini', '旅拍攝影師', '我在威尼斯從事旅拍攝影工作，最喜歡清晨安靜的運河、老建築光影與旅人穿梭巷弄的畫面。因為熟悉人潮與時間，我能安排較舒服的拍攝路線，避開最擁擠的角落。無論是獨旅、情侶或家人，我都會用自然引導留下屬於你們的威尼斯記憶。', '/images/hosts/host-29.jpg'),
(30, 'Núria Vidal', '旅拍攝影師', '我是巴塞隆納旅拍攝影師，擅長結合建築線條、陽光色彩與人物動態，拍出明亮有活力的旅行照片。從海邊、舊城區到高第建築周邊，都有很適合留下故事的場景。我會先了解你的穿搭和期待，再用不尷尬的互動方式完成拍攝，讓照片保有自然個性。', '/images/hosts/host-30.jpg'),

(31, 'Harry Collins', '夜生活達人', '我是倫敦夜生活達人，熟悉西區音樂劇、老酒吧、現場音樂與夜間市集文化。我的推薦不只看熱門程度，更重視安全、交通便利與是否適合不同旅行風格。無論你想安靜喝一杯、聽爵士樂或感受熱鬧派對，我都會分享實用資訊，讓你安心享受倫敦迷人的夜晚。', '/images/hosts/host-31.jpg'),
(32, 'Léa Girard', '夜生活達人', '我是巴黎夜生活達人，喜歡探索左岸小酒館、屋頂酒吧、深夜甜點店與現場表演空間。巴黎的夜晚不是只有華麗派對，也有很多適合慢慢聊天、觀察城市的角落。我會依旅人的喜好安排節奏，並提醒交通與安全細節，讓大家用舒服方式感受巴黎入夜後的魅力。', '/images/hosts/host-32.jpg'),
(33, 'Niklas Reuter', '夜生活達人', '我住在慕尼黑，熟悉啤酒館、精釀酒吧、音樂表演與季節性慶典活動。巴伐利亞夜生活有熱鬧的一面，也有很重視聊天與社群交流的傳統。我會介紹適合第一次到訪者的選擇、飲酒禮儀與返程交通，讓旅人能放心體驗慕尼黑晚上真誠又熱情的氣氛。', '/images/hosts/host-33.jpg'),
(34, 'Eva Meijer', '夜生活達人', '我是阿姆斯特丹夜生活達人，熟悉運河酒吧、電子音樂場館、深夜餐館與獨立表演空間。我相信好的夜晚不只是喝酒，而是找到適合自己的節奏與同伴。我會提供安全移動、預約方式和街區氛圍建議，幫助旅人在尊重當地文化的前提下，享受阿姆斯特丹自由又多元的夜色。', '/images/hosts/host-34.jpg'),
(35, 'Alessandro Gallo', '夜生活達人', '我是威尼斯夜生活達人，喜歡帶旅人認識小酒館、傳統開胃酒文化與夜晚較安靜的運河景色。威尼斯的夜不一定喧鬧，更多時候是慢慢喝一杯、聽水聲和欣賞燈光倒影。我會分享適合夜遊的區域、在地酒單與安全返程方式，讓你體驗優雅而有溫度的威尼斯夜晚。', '/images/hosts/host-35.jpg'),
(36, 'Clara Montes', '夜生活達人', '我是巴塞隆納夜生活達人，熟悉佛朗明哥表演、小型音樂場館、海邊酒吧與深夜小吃文化。這座城市的夜晚充滿節奏，但也需要掌握安全與在地習慣。我會依照旅人的興趣推薦合適去處，分享入場規則、交通與點餐方式，讓大家盡情感受巴塞隆納熱情又有層次的夜生活。', '/images/hosts/host-36.jpg');

-- --------------------------------------------------------
-- Seed data for `experiences`
-- 100 experiences; images and sessions use IDs 1 to 100


-- Continue AUTO_INCREMENT after imported seed data
ALTER TABLE `experiences` AUTO_INCREMENT = 101;

-- --------------------------------------------------------
-- Seed data for `sessions`
-- 共 100 個體驗 × 60 天 × 每天 2 場 = 12000 筆

-- 只有在 sessions 是空資料表、重新匯入 seed 時才需要這行
ALTER TABLE sessions AUTO_INCREMENT = 1;

  experience_id,
  start_time,
  end_time,
  booking_deadline,
  adult_price,
  child_price,
  min_participants,
  max_participants,
  status,
  created_at
)
WITH RECURSIVE historical_dates AS (
  -- 歷史場次：2026/06/15～07/14，共 30 天
  SELECT DATE('2026-06-15') AS session_date

  UNION ALL

  SELECT DATE_ADD(session_date, INTERVAL 1 DAY)
  FROM historical_dates
  WHERE session_date < DATE('2026-07-14')
),

future_dates AS (
  -- 可預訂場次：2026/08/06～09/04，共 30 天
  SELECT DATE('2026-08-06') AS session_date

  UNION ALL

  SELECT DATE_ADD(session_date, INTERVAL 1 DAY)
  FROM future_dates
  WHERE session_date < DATE('2026-09-04')
),

date_list AS (
  SELECT session_date FROM historical_dates
  UNION ALL
  SELECT session_date FROM future_dates
),

session_schedule AS (
  -- category_id, 第幾場, 開始時間, 體驗分鐘數

  -- 古蹟巡禮
  SELECT 1 AS category_id, 1 AS slot_no, '09:30:00' AS start_at, 150 AS duration_minutes
  UNION ALL SELECT 1, 2, '14:00:00', 150

  -- 藝文導覽
  UNION ALL SELECT 2, 1, '10:00:00', 150
  UNION ALL SELECT 2, 2, '14:30:00', 150

  -- 美饌饗宴：午餐、晚餐
  UNION ALL SELECT 3, 1, '12:00:00', 180
  UNION ALL SELECT 3, 2, '18:30:00', 180

  -- 戶外探索
  UNION ALL SELECT 4, 1, '09:00:00', 240
  UNION ALL SELECT 4, 2, '14:00:00', 240

  -- 專人攝影
  UNION ALL SELECT 5, 1, '10:00:00', 120
  UNION ALL SELECT 5, 2, '15:00:00', 120

  -- 娛樂與夜生活：晚上場
  UNION ALL SELECT 6, 1, '19:00:00', 210
  UNION ALL SELECT 6, 2, '21:30:00', 210
),

experience_base_price AS (
  SELECT
    e.id AS experience_id,
    e.category_id,

    CASE e.category_id
      WHEN 1 THEN 2000 + MOD(e.id, 5) * 100
      WHEN 2 THEN 2400 + MOD(e.id, 5) * 150
      WHEN 3 THEN 2200 + MOD(e.id, 5) * 200
      WHEN 4 THEN 1600 + MOD(e.id, 5) * 100
      WHEN 5 THEN 2800 + MOD(e.id, 5) * 250
      WHEN 6 THEN 2400 + MOD(e.id, 5) * 200
      ELSE 2000
    END AS weekday_adult_price

  FROM experiences e
  WHERE e.id BETWEEN 1 AND 100
)

SELECT
  e.experience_id,

  TIMESTAMP(d.session_date, ss.start_at) AS start_time,

  DATE_ADD(
    TIMESTAMP(d.session_date, ss.start_at),
    INTERVAL ss.duration_minutes MINUTE
  ) AS end_time,

  DATE_SUB(
    TIMESTAMP(d.session_date, ss.start_at),
    INTERVAL 24 HOUR
  ) AS booking_deadline,

  ROUND(
    e.weekday_adult_price *
    CASE
      WHEN DAYOFWEEK(d.session_date) IN (1, 7) THEN 1.2
      ELSE 1
    END,
    0
  ) AS adult_price,

  ROUND(
    e.weekday_adult_price * 0.7 *
    CASE
      WHEN DAYOFWEEK(d.session_date) IN (1, 7) THEN 1.2
      ELSE 1
    END,
    0
  ) AS child_price,

  2 AS min_participants,
  8 AS max_participants,
  1 AS status,
  NOW() AS created_at

FROM date_list d
CROSS JOIN session_schedule ss
INNER JOIN experience_base_price e
  ON e.category_id = ss.category_id

-- 這個排序讓第一天第一場的 ID 1～100，
-- 分別對應 experience_id 1～100
ORDER BY
  d.session_date ASC,
  ss.slot_no ASC,
  e.experience_id ASC;

-- --------------------------------------------------------
-- Seed data for `posts`

  `title`,
  `slug`,
  `content`,
  `excerpt`,
  `cover_image`,
  `content_image`,
  `status`,
  `published_at`,
  `updated_at`,
  `created_at`,
  `author_id`,
  `category_id`,
  `order_item_id`,
  `experience_id`,
  `review_note`
)
WITH
city_copy AS (
  SELECT 1 AS city_order, '倫敦' AS city_name, 'london' AS city_key,
    'London' AS image_folder,
    '紅磚街區、河岸天際線與市場日常彼此交錯，適合用步行速度慢慢閱讀城市層次。' AS city_note
  UNION ALL
  SELECT 2, '巴黎', 'paris', 'Paris',
    '林蔭大道、街角咖啡館與歷史建築形成自然的生活舞台，白天與傍晚各有不同光線。'
  UNION ALL
  SELECT 3, '阿姆斯特丹', 'amsterdam', 'Amsterdam',
    '運河、窄屋與單車節奏構成鮮明風景，適合安排留白，觀察水面倒影與街區細節。'
  UNION ALL
  SELECT 4, '巴塞隆納', 'barcelona', 'Barcelona',
    '海岸陽光、現代主義建築與熱鬧街區並存，行程可以在文化觀察與放鬆之間取得平衡。'
  UNION ALL
  SELECT 5, '慕尼黑', 'munich', 'Munich',
    '王室建築、綠地與在地餐桌文化距離不遠，適合以明確主題串成一條舒適路線。'
  UNION ALL
  SELECT 6, '威尼斯', 'venice', 'Venice',
    '水巷、石橋與廣場會隨光線改變表情，避開急促打卡，更能感受城市獨特的尺度。'
),
category_copy AS (
  SELECT 1 AS category_id, '古蹟巡禮' AS category_label,
    '古城散步精選' AS title_one, '歷史街區指南' AS title_two,
    '觀察建築年代、城市紋理與街道格局，不只記住地標名稱，也理解不同時期如何共同塑造今日風景。' AS editorial_focus,
    '建議先掌握主要歷史節點，再把周邊巷弄與廣場排入路線；鞋子以好走為優先，並為臨時停留保留時間。' AS practical_focus
  UNION ALL
  SELECT 2, '藝文導覽', '藝術漫遊精選', '美術館散步',
    '把作品、展館空間與城市背景放在同一條敘事線上，讓藝術不只停留在展品說明，而能連回旅行當下的感受。',
    '大型展館不必一次看完，先選一至兩個主題；遇到喜歡的作品多停幾分鐘，比追求打卡數量更有收穫。'
  UNION ALL
  SELECT 3, '美饌饗宴', '餐桌風味精選', '在地美食指南',
    '從市場食材、料理方法與用餐節奏認識地方文化，重點不只是吃到名店，也包括理解一道菜為何出現在這座城市。',
    '熱門餐廳可先訂位，同時保留一餐給市場或街區小店；若有過敏與飲食限制，應在預約時清楚確認。'
  UNION ALL
  SELECT 4, '戶外探索', '戶外路線精選', '自然散步指南',
    '透過河岸、公園、海邊或城市近郊轉換觀看角度，在移動與停留之間找到適合自己的體力節奏。',
    '出發前確認天氣與日落時間，準備飲水、防曬和輕便外套；路線不必塞滿，安全與舒適應放在第一位。'
  UNION ALL
  SELECT 5, '專人攝影', '旅拍場景精選', '城市取景指南',
    '利用街道線條、自然光與城市色彩留下有情境的旅行影像，讓人物和環境彼此呼應，而不是只更換拍照背景。',
    '服裝以活動方便且色彩簡潔為佳，拍攝前可整理喜歡的氛圍參考；遇到人潮時，耐心等待通常比頻繁換點有效。'
  UNION ALL
  SELECT 6, '娛樂與夜生活', '夜間行程精選', '夜生活指南',
    '從表演、酒館、夜景與晚間街區感受城市下班後的樣貌，安排重點是氣氛、移動安全與結束時間。',
    '先確認演出入場規定與末班交通，飲酒保持適量；夜間移動以明亮主要道路為主，回程預留叫車備案。'
),
normalized_experiences AS (
  SELECT
    e.id,
    e.category_id,
    e.title,
    CASE
      WHEN e.city = '巴賽隆納' THEN '巴塞隆納'
      ELSE e.city
    END AS city_name,
    e.city AS original_city
  FROM `experiences` AS e
),
ranked_experiences AS (
  SELECT
    ne.id,
    ne.category_id,
    ne.title,
    ne.city_name,
    ROW_NUMBER() OVER (
      PARTITION BY ne.city_name, ne.category_id
      ORDER BY
        CASE
          WHEN ne.original_city = ne.city_name THEN 0
          ELSE 1
        END,
        ne.id
    ) AS choice_order
  FROM normalized_experiences AS ne
  INNER JOIN city_copy AS cc
    ON cc.city_name = ne.city_name
),
city_category_experiences AS (
  SELECT
    re.id AS experience_id,
    re.category_id,
    re.title AS experience_title,
    cc.city_order,
    cc.city_name,
    cc.city_key,
    cc.image_folder,
    cc.city_note,
    cat.category_label,
    cat.title_one,
    cat.title_two,
    cat.editorial_focus,
    cat.practical_focus
  FROM ranked_experiences AS re
  INNER JOIN city_copy AS cc
    ON cc.city_name = re.city_name
  INNER JOIN category_copy AS cat
    ON cat.category_id = re.category_id
  WHERE re.choice_order = 1
),
article_numbers AS (
  SELECT 1 AS article_number
  UNION ALL
  SELECT 2
),
article_source AS (
  SELECT
    combo.*,
    numbers.article_number,
    MOD(
      combo.city_order + combo.category_id + numbers.article_number,
      6
    ) AS layout_variant,
    ((combo.category_id - 1) * 4)
      + ((numbers.article_number - 1) * 2)
      + 1 AS cover_number,
    (
      (
        ((combo.category_id - 1) * 2)
        + (numbers.article_number - 1)
      ) * 6
    ) + (combo.city_order - 1) AS publish_order,
    CASE
      WHEN numbers.article_number = 1
        THEN '以第一次造訪者的角度安排重點，先建立清楚方向，再把現場感受留給步行途中慢慢補上。'
      ELSE '以想看得更深入的旅人為出發點，避開只追逐熱門清單，改用主題、時間與街區氣氛組織行程。'
    END AS article_angle,
    CASE
      WHEN numbers.article_number = 1
        THEN '上午先處理最需要專注的內容，中段安排休息，傍晚再用較輕鬆的方式收尾。'
      ELSE '先選一個核心體驗，再搭配周邊一至兩個停留點，讓移動距離合理，也保留臨時改變計畫的彈性。'
    END AS route_advice
  FROM city_category_experiences AS combo
  CROSS JOIN article_numbers AS numbers
)
SELECT
  CONCAT(
    source.city_name,
    CASE
      WHEN source.article_number = 1 THEN source.title_one
      ELSE source.title_two
    END
  ) AS title,

  CONCAT(
    'official-',
    source.city_key,
    '-category-',
    source.category_id,
    '-',
    source.article_number
  ) AS slug,

  CONCAT(
    '<h2>',
    source.city_name,
    '｜',
    source.category_label,
    CASE
      WHEN source.article_number = 1 THEN '編輯精選'
      ELSE '深度指南'
    END,
    '</h2>',

    CASE source.layout_variant
      WHEN 0 THEN CONCAT(
        '<figure class="image"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, source.category_label,
        '"><figcaption>', source.city_name, '的',
        source.category_label, '旅行視角</figcaption></figure>',
        '<p><span class="marker-yellow">編輯部路線觀察：</span>',
        source.city_note, source.article_angle,
        '這篇內容以「', source.experience_title,
        '」作為認識城市的起點。', source.editorial_focus,
        '實際安排時不必急著把所有景點塞進一天，先確定最想理解的主題，旅程會更有記憶點。</p>',
        '<blockquote><p>', source.route_advice,
        '若現場狀況與預期不同，也可以縮短次要停留，把時間留給真正喜歡的地方。</p></blockquote>',
        '<p>', source.practical_focus,
        '此外，交通、營業時間與預約規則可能因季節調整，出發前仍應查看最新公告。好的行程不是完成最多項目，而是在適合的節奏裡看見城市細節，並帶著足夠餘裕安全返回。</p>'
      )

      WHEN 1 THEN CONCAT(
        '<figure class="image image-style-side"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, source.category_label, '側景"></figure>',
        '<p><span class="marker-green">從一個主題開始：</span>',
        source.city_note, '本篇選擇「', source.experience_title,
        '」作為核心，是因為它能把地點、故事與實際參與感連在一起。', source.editorial_focus,
        source.article_angle,
        '與其把文章當成固定答案，更適合把它視為可依天氣、同行者與體力調整的行程底稿。</p>',
        '<h3>安排時先確認</h3>',
        '<ul><li>核心體驗的集合時間、語言及入場方式</li>',
        '<li>體驗前後的移動距離與休息地點</li>',
        '<li>當日天氣、服裝及必要預約</li></ul>',
        '<div class="page-break"></div>',
        '<p>', source.route_advice, source.practical_focus,
        '如果只剩半天，也可以保留核心內容並刪除繞路景點；如果時間充足，則可在附近安排一段沒有目的的散步。這種鬆緊交替的節奏，更容易留下屬於自己的城市印象。</p>'
      )

      WHEN 2 THEN CONCAT(
        '<blockquote><p>旅行不必把每個地標都變成任務；選對觀看角度，比增加清單長度更重要。</p></blockquote>',
        '<p>', source.city_name, '的', source.category_label,
        '適合先從「', source.experience_title,
        '」建立方向。', source.city_note, source.editorial_focus,
        source.article_angle,
        '編輯部建議在出發前只設定一個主要目標，其他停留則依現場氣氛決定，既能避免趕路，也不會失去探索感。</p>',
        '<figure class="image"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, source.category_label,
        '"><figcaption>為主要體驗前後保留散步時間</figcaption></figure>',
        '<figure class="table"><table><tbody>',
        '<tr><th>時間安排</th><td>', source.route_advice, '</td></tr>',
        '<tr><th>現場準備</th><td>', source.practical_focus, '</td></tr>',
        '<tr><th>編輯提醒</th><td>保留備案並確認最新營業資訊，不因拍照或打卡影響安全。</td></tr>',
        '</tbody></table></figure>',
        '<p>完成主要體驗後，可以找一個安靜位置整理照片與筆記，再決定是否繼續下一站。這段整理時間能讓資訊沉澱，也能及早察覺疲勞。只要主題清楚，即使行程不長，仍能形成完整而有層次的一天。</p>'
      )

      WHEN 3 THEN CONCAT(
        '<p><span class="marker-blue">本日提案：</span>用',
        source.category_label, '重新閱讀', source.city_name,
        '。', source.city_note, '我們以「', source.experience_title,
        '」為路線核心，並把附近街區當成延伸而非附加任務。', source.editorial_focus,
        source.article_angle,
        '這樣安排可以降低交通轉換，也能在同一區域裡看見白天與傍晚不同的表情。</p>',
        '<figure class="image image-style-side"><img src="/',
