-- Seed data for `experience_images`
-- 100 個體驗 × 每個體驗 5 張圖片 = 500 筆

ALTER TABLE experience_images AUTO_INCREMENT = 1;

  experience_id,
  image_url,
  is_primary,
  sort_order,
  created_at
)
WITH RECURSIVE experience_numbers AS (
  SELECT 1 AS experience_id

  UNION ALL

  SELECT experience_id + 1
  FROM experience_numbers
  WHERE experience_id < 100
),

image_numbers AS (
  SELECT 1 AS image_number

  UNION ALL

  SELECT image_number + 1
  FROM image_numbers
  WHERE image_number < 5
)

SELECT
  e.experience_id,

  CONCAT(
    '/images/experiences/exp-',
    e.experience_id,
    '/',
    i.image_number,
    '.jpg'
  ) AS image_url,

  CASE
    WHEN i.image_number = 1 THEN 1
    ELSE 0
  END AS is_primary,

  i.image_number AS sort_order,

  NOW() AS created_at

FROM experience_numbers e
CROSS JOIN image_numbers i
ORDER BY e.experience_id, i.image_number;


-- 訂單建立日：統一早於 2026/6/15 起的歷史場次
UPDATE order_main
SET
  created_at = DATE_ADD(
    '2026-06-01 09:00:00',
    INTERVAL MOD(CAST(RIGHT(id, 4) AS UNSIGNED) - 1, 10) DAY
  ),
  updated_at = DATE_ADD(
    '2026-06-01 09:00:00',
    INTERVAL MOD(CAST(RIGHT(id, 4) AS UNSIGNED) - 1, 10) DAY
  )
WHERE id LIKE 'EU26R%';
