-- Seed data for `order_items`：共 1,000 筆


-- 補 200 筆，讓 order_items 總數成為 1,000。
  id, order_id, experience_id, session_id, original_unit_price,
  quantity, subtotal, item_status, special_request, updated_at
)
WITH RECURSIVE item_numbers AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1 FROM item_numbers WHERE n < 200
),
targets AS (
  SELECT
    n,
    MOD(n + 49, 100) + 1 AS experience_id,
    CONCAT('EU26R', LPAD(n, 4, '0')) AS order_id,
    DATE_ADD('2026-06-15', INTERVAL MOD(n - 1, 30) DAY) AS session_date
  FROM item_numbers
),
historical_sessions AS (
  SELECT
    experience_id,
    DATE(start_time) AS session_date,
    MIN(id) AS session_id,
    MIN(adult_price) AS adult_price
  FROM sessions
  WHERE start_time >= '2026-06-15'
    AND start_time < '2026-07-15'
  GROUP BY experience_id, DATE(start_time)
)
SELECT
  1052 + t.n,
  t.order_id,
  t.experience_id,
  s.session_id,
  s.adult_price,
  1,
  s.adult_price,
  'confirmed',
  '補充評價測試用訂單明細',
  DATE_SUB(s.session_date, INTERVAL 7 DAY)
FROM targets t
JOIN historical_sessions s
  ON s.experience_id = t.experience_id
  AND s.session_date = t.session_date;


