-- 我新增 004_update_sessions_booking_deadline.sql 用途：統一 sessions 報名截止時間為 start_time 前 24 小時

UPDATE sessions
SET booking_deadline = DATE_SUB(start_time, INTERVAL 24 HOUR)
WHERE status = 1;




