INSERT INTO hosts (id, name, role, bio, avatar) VALUES
(1, 'Oliver Bennett', '文史導覽員', '我是土生土長的倫敦人，長期研究泰晤士河沿岸、英國王室與工業革命留下的城市痕跡。帶團時不只介紹知名景點，也會分享巷弄裡的歷史故事、老酒館文化與居民生活。我希望每位旅人離開倫敦後，都能記得這座城市真正的聲音與節奏。', '/images/hosts/host-1.jpg'),
(2, 'Camille Moreau', '文史導覽員', '我是巴黎人，也是專注城市歷史的導覽工作者。從塞納河兩岸、中世紀街區到法國大革命留下的建築，我喜歡把複雜歷史說成容易理解的旅行故事。走在巴黎街頭時，我會帶你看見觀光地圖以外的細節，認識這座城市如何一步步形成今天的樣子。', '/images/hosts/host-2.jpg'),
(3, 'Leonhard Fischer', '文史導覽員', '我在慕尼黑成長，對巴伐利亞王室、啤酒文化與老城建築有濃厚興趣。多年來持續整理地方史料，也習慣用輕鬆方式分享城市背景。我的導覽會結合廣場、教堂與市集故事，讓旅人不只是拍照打卡，而是真的理解慕尼黑人的日常與傳統。', '/images/hosts/host-3.jpg'),
(4, 'Sophie van Dijk', '文史導覽員', '我是阿姆斯特丹在地人，喜歡研究運河、商業貿易與城市自由精神之間的關係。從黃金時代的倉庫建築到今日居民使用的自行車路線，都藏著豐富故事。我會用平易近人的方式帶你理解這座水上城市，並分享最適合慢慢散步、觀察生活的街區角落。', '/images/hosts/host-4.jpg'),
(5, 'Giulia Conti', '文史導覽員', '我出生在威尼斯潟湖旁，從小就在橋梁、運河與狹窄巷弄間長大。除了熟悉聖馬可廣場的歷史，我更喜歡介紹居民仍在使用的市場、工坊與安靜小教堂。我的導覽不追求匆忙踩點，而是帶旅人理解威尼斯如何在水與陸地之間維持獨特生活。', '/images/hosts/host-5.jpg'),
(6, 'Marc Soler', '文史導覽員', '我是巴塞隆納人，專研加泰隆尼亞歷史、城市建築與地方認同。高第作品固然迷人，但我也喜歡從市場、廣場和街區傳說談這座城市。導覽過程中會帶你認識巴塞隆納的文化脈絡，讓你理解它不只是陽光海岸城市，更是一座充滿個性與故事的地方。', '/images/hosts/host-6.jpg'),
INSERT INTO `experiences` (`id`, `category_id`, `host_id`, `title`, `description`, `meeting_point`, `city`, `longitude`, `latitude`, `created_at`) VALUES
(1, 5, 25, '倫敦經典街景自然光旅拍', '由專業攝影師帶領，在倫敦經典街區捕捉自然生動的人像。走訪大笨鐘、紅色電話亭與泰晤士河畔等代表性場景。攝影師會提供簡單易懂的姿勢與取景指導，即使第一次拍攝也能自在入鏡。行程結束後將獲得精選調色照片，留下專屬於你的倫敦旅行回憶。', 'Westminster Station 1 號出口', '倫敦', -0.124625, 51.500729, '2026-07-13 12:05:00'),
(2, 2, 8, '羅浮宮經典藝術深度導覽之旅', '由專業藝文導覽員帶領，認識羅浮宮重要館藏與建築歷史。精選蒙娜麗莎、米洛的維納斯與勝利女神等經典作品進行解說。透過作品背後的時代故事與創作細節，輕鬆理解西方藝術發展。適合第一次造訪羅浮宮的旅客，在有限時間內掌握最具代表性的藝術精華。', '羅浮宮玻璃金字塔入口附近', '巴黎', 2.337644, 48.860611, '2026-07-13 12:10:00'),
(3, 3, 14, '法餐私廚經典料理品味之夜', '走進巴黎私廚餐桌，品嚐以當季食材設計的經典法式料理。由主廚介紹每道菜的烹調方式、食材來源與法國飲食文化。餐點包含前菜、主餐及甜點，並搭配適合的葡萄酒或無酒精飲品。透過小班制用餐與主廚交流，在自在氛圍中感受巴黎人的精緻生活。', '巴黎瑪黑區聖保羅地鐵站出口', '巴黎', 2.360137, 48.855281, '2026-07-13 12:15:00'),
(4, 4, 22, '腳踏車市區深度探索漫遊之旅', '騎乘舒適的城市腳踏車，跟著在地嚮導探索阿姆斯特丹的大街小巷。沿途經過運河、特色橋梁與充滿生活感的社區。導覽員將分享城市發展、自行車文化與居民的日常故事。行程步調輕鬆並安排多次停留，適合具備基本騎乘能力的旅客。', '阿姆斯特丹中央車站正門廣場', '阿姆斯特丹', 4.900272, 52.379189, '2026-07-13 12:20:00'),
(5, 1, 6, '聖家堂建築藝術古蹟深度導覽', '由專業導覽員帶領，深入認識聖家堂的建築構造與歷史背景。欣賞高第運用自然光線、幾何圖形與宗教意象打造的空間。透過立面雕刻與教堂內部細節，了解不同時期的設計故事。適合喜愛建築與文化的旅客，完整感受巴塞隆納最具代表性的地標。', '聖家堂誕生立面入口附近', '巴塞隆納', 2.174355, 41.403629, '2026-07-13 12:25:00'),
(6, 6, 32, '瘋馬秀巴黎華麗夜間表演體驗', '走進巴黎知名的瘋馬秀劇場，欣賞融合舞蹈、燈光與舞台藝術的精彩演出。表演以精準編舞和視覺效果呈現充滿法式風格的夜間娛樂。舒適的劇院環境讓旅客能近距離感受專業舞者的舞台魅力。適合安排在巴黎夜遊行程中，體驗不同於白天觀光的城市氣氛。', 'Crazy Horse Paris 劇場入口', '巴黎', 2.301132, 48.865925, '2026-07-13 12:30:00'),
(7, 6, 31, '悲慘世界音樂劇經典劇院之夜', '走進倫敦西區劇院，欣賞改編自經典文學作品的悲慘世界音樂劇。透過氣勢磅礴的歌曲、細膩演技與舞台設計感受劇情張力。演出呈現愛、犧牲與希望等動人主題，即使初次接觸音樂劇也能投入其中。適合喜愛表演藝術的旅客，體驗倫敦夜晚最具代表性的文化活動。', 'Sondheim Theatre 正門入口', '倫敦', -0.131286, 51.511099, '2026-07-13 12:35:00'),
(8, 4, 23, '貢多拉遊船水都浪漫探索之旅', '搭乘威尼斯傳統貢多拉，沿著蜿蜒水道欣賞水都特有的城市景觀。船夫將帶領旅客穿過小運河、古老石橋與歷史建築之間。從水面角度觀察威尼斯的生活細節，感受與步行觀光不同的旅行節奏。適合情侶、家人與初次造訪的旅客，留下浪漫而經典的水都回憶。', '聖馬可廣場鐘樓附近', '威尼斯', 12.338176, 45.434035, '2026-07-13 12:40:00'),
(9, 6, 33, '啤酒節慕尼黑經典狂歡之夜', '走進慕尼黑熱鬧的啤酒節會場，感受巴伐利亞最具代表性的節慶氣氛。品嚐當地啤酒與傳統料理，並認識不同酒款及飲食文化。現場樂隊、民族服飾與大型帳篷共同營造歡樂的夜間體驗。由熟悉會場的帶隊人員協助安排動線，讓旅客安心參與這場城市盛會。', 'Theresienwiese 地鐵站出口', '慕尼黑', 11.549143, 48.131929, '2026-07-13 12:45:00'),
(10, 6, 32, '紅磨坊歌舞盛宴璀璨巴黎之夜', '走進巴黎蒙馬特的紅磨坊劇場，欣賞充滿華麗服裝與舞台效果的歌舞演出。專業舞者以經典康康舞、音樂與燈光呈現法式夜生活魅力。劇院歷史悠久且氣氛熱鬧，讓旅客感受巴黎娛樂文化的代表性場景。適合安排為旅行中的特別夜晚，在璀璨演出中留下難忘回憶。', 'Moulin Rouge 劇場正門入口', '巴黎', 2.332260, 48.884139, '2026-07-13 12:50:00'),
(11, 5, 25, '倫敦塔橋晨光人像寫真旅拍', '在清晨柔和光線下拍攝倫敦塔橋與泰晤士河畔景色。攝影師會協助引導自然姿勢與適合你的拍照角度。行程包含橋邊街景與具有倫敦特色的建築背景。結束後將提供精選修圖照片，留下專屬倫敦回憶。', 'Tower Bridge 正門', '倫敦', -0.075400, 51.505500, '2026-07-21 18:43:34'),
(12, 2, 8, '巴黎羅浮宮藝術名作深度導覽', '由導覽員帶領認識羅浮宮最具代表性的館藏與故事。用容易理解的方式欣賞蒙娜麗莎與古典人體藝術作品。行程也會分享建築改建與宮殿歷史留下的重要痕跡。適合第一次參觀羅浮宮又想深入了解藝術的旅人。', 'Musée du Louvre 金字塔入口', '巴黎', 2.336400, 48.860600, '2026-07-21 18:43:34'),
(13, 6, 33, '慕尼黑啤酒花園微醺夜遊體驗', '走進慕尼黑當地人喜愛的傳統啤酒花園感受夜晚氣氛。認識不同德國啤酒風味與巴伐利亞飲酒文化特色。品嚐經典香腸、椒鹽捲餅與適合搭配的在地小食。適合想輕鬆認識慕尼黑夜生活的成年旅人。', 'Marienplatz 新市政廳前', '慕尼黑', 11.575500, 48.137400, '2026-07-21 18:43:34'),
(14, 1, 4, '阿姆斯特丹王宮歷史文化導覽', '從水壩廣場出發認識阿姆斯特丹王宮與城市發展故事。導覽員會介紹荷蘭黃金時代留下的重要建築與文化。沿途欣賞老城街道、運河景觀和具有特色的山形屋。適合喜歡歐洲歷史建築與城市文化的旅人。', 'Dam Square 水壩廣場', '阿姆斯特丹', 4.891000, 52.373100, '2026-07-21 18:43:34'),
(15, 1, 5, '威尼斯聖馬可廣場古蹟巡禮', '走訪聖馬可廣場周邊的重要建築與威尼斯共和國歷史。認識聖馬可大教堂、鐘樓和總督宮背後的城市故事。導覽員會分享威尼斯商業繁盛時期留下的文化痕跡。適合第一次造訪威尼斯並想掌握必看景點的旅人。', 'Piazza San Marco 廣場入口', '威尼斯', 12.337000, 45.434000, '2026-07-21 18:43:34'),
(16, 3, 18, '巴塞隆納海鮮燉飯料理體驗', '跟著主廚前往市場挑選當季海鮮與西班牙特色食材。學習製作香氣濃郁的傳統海鮮燉飯與經典小菜。課程會介紹橄欖油、香料和高湯對風味的重要影響。完成後能和同行旅人一起享用親手製作的料理。', 'Mercat de la Boqueria 正門', '巴塞隆納', 2.171800, 41.382600, '2026-07-21 18:43:34'),
(17, 4, 19, '倫敦泰晤士河畔健走探索', '沿著泰晤士河步行欣賞倫敦眼、大笨鐘與河岸風景。導覽員會分享河畔地標與倫敦城市發展的有趣故事。路線安排平緩好走，也會保留時間讓旅人拍照休息。適合喜歡輕鬆散步並認識倫敦經典景點的旅人。', 'London Eye 入口前', '倫敦', -0.119500, 51.503300, '2026-07-21 18:43:34'),
(18, 3, 14, '巴黎左岸法式私廚饗宴體驗', '在巴黎左岸溫馨私廚中品嚐道地法式家常料理。主廚會介紹每道菜的食材來源與傳統烹調方式。餐點搭配當季甜點與適合佐餐的法國飲品選擇。適合想用一頓晚餐深入感受巴黎生活風格的旅人。', 'Saint-Germain-des-Prés 地鐵站出口', '巴黎', 2.333300, 48.853800, '2026-07-21 18:43:34'),
(19, 2, 9, '慕尼黑當代藝術美術館導覽', '走進慕尼黑現代藝術空間認識歐洲當代創作的特色。導覽員會用淺顯方式說明作品背後的概念與時代背景。行程包含建築特色、重要展品和藝術家的創作故事。適合想輕鬆接觸當代藝術又不想自己查資料的旅人。', 'Pinakothek der Moderne 正門', '慕尼黑', 11.573700, 48.148400, '2026-07-21 18:43:34'),
(20, 4, 22, '阿姆斯特丹運河單車探索之旅', '騎乘單車穿梭阿姆斯特丹經典運河與安靜住宅街區。沿途停靠特色橋梁、花市與當地人才知道的小景點。導覽員會分享荷蘭單車文化和城市規劃的生活故事。路線平緩好騎，適合想以自在步調認識城市的旅人。', 'Amsterdam Centraal Station 前廣場', '阿姆斯特丹', 4.900300, 52.379100, '2026-07-21 18:43:34'),
(21, 1, 5, '威尼斯總督宮歷史文化導覽', '走進總督宮認識威尼斯共和國最輝煌時期的政治與藝術歷史。導覽員會介紹議事廳、華麗壁畫和宮殿建築細節。行程也會分享總督宮與聖馬可廣場的重要故事。適合喜歡歐洲歷史與古典建築的旅人。', 'Palazzo Ducale 正門', '威尼斯', 12.340800, 45.433700, '2026-07-21 19:30:58'),
(22, 2, 11, '威尼斯玻璃工藝藝術導覽體驗', '前往充滿工藝氣息的玻璃工坊認識威尼斯傳統製作技術。了解玻璃工匠如何利用高溫塑造出細緻的藝術作品。現場可欣賞不同色彩與造型背後代表的設計巧思。適合喜歡手作藝術和特色紀念品的旅人。', 'Fondamenta Nove 碼頭', '威尼斯', 12.347600, 45.444600, '2026-07-21 19:30:58'),
(23, 5, 29, '威尼斯運河人像旅拍寫真體驗', '由在地攝影師帶你走進威尼斯運河旁的特色巷弄取景。拍攝過程會引導自然姿勢，讓不常拍照的人也能放鬆。行程包含經典橋景、水道與充滿電影感的街道背景。結束後提供精選照片，留下專屬威尼斯回憶。', 'Rialto Bridge 橋頭', '威尼斯', 12.335800, 45.438000, '2026-07-21 19:30:58'),
(24, 1, 6, '巴塞隆納哥德區古蹟巡禮導覽', '漫步巴塞隆納哥德區，認識中世紀街道與城市發展歷程。導覽員會介紹主教座堂、古羅馬遺跡與隱藏廣場故事。沿途可欣賞狹窄巷弄中保存良好的歷史建築細節。適合第一次到巴塞隆納又喜歡老城風景的旅人。', 'Barcelona Cathedral 正門', '巴塞隆納', 2.176900, 41.383900, '2026-07-21 19:30:58'),
(25, 2, 12, '巴塞隆納高第建築藝術導覽', '從高第獨特的建築語言認識巴塞隆納的藝術城市風格。導覽會介紹曲線結構、自然元素和馬賽克裝飾的設計概念。行程包含重要地標周邊與適合拍攝建築細節的位置。適合喜歡設計、建築與藝術文化的旅人。', 'Casa Batlló 門口', '巴塞隆納', 2.164900, 41.391700, '2026-07-21 19:30:58'),
(26, 5, 30, '巴塞隆納街頭人像旅拍體驗', '跟著攝影師走進巴塞隆納充滿色彩的街道與特色廣場。依照你的穿搭和風格安排適合的人像拍攝角度與背景。過程中會捕捉自然互動與旅行途中最放鬆的瞬間。完成後提供精選修圖照片，留下鮮明的城市回憶。', 'Arc de Triomf 前', '巴塞隆納', 2.180900, 41.391100, '2026-07-21 19:30:58'),
(27, 2, 9, '慕尼黑宮廷藝術博物館導覽', '走進慕尼黑宮廷博物館認識巴伐利亞王室留下的藝術收藏。導覽員會介紹珍貴畫作、珠寶與華麗宮廷空間的歷史。用淺顯方式說明藝術品背後的人物故事與時代背景。適合想深入認識德國歷史文化的旅人。', 'Residenz München 正門', '慕尼黑', 11.577800, 48.142200, '2026-07-21 19:30:58'),
(28, 3, 15, '慕尼黑傳統市集美食體驗之旅', '走訪慕尼黑人氣市集，品嚐香腸、起司與當季烘焙點心。導覽員會介紹巴伐利亞飲食文化和食材搭配的習慣。沿途可嘗試在地人常買的小吃與經典啤酒花園料理。適合想用味覺快速認識慕尼黑生活的旅人。', 'Viktualienmarkt 正門', '慕尼黑', 11.576100, 48.135100, '2026-07-21 19:30:58'),
(29, 5, 28, '阿姆斯特丹運河人像旅拍體驗', '在阿姆斯特丹運河與山形屋背景前拍下自然旅行寫真照片。攝影師會依照光線和街景安排適合你的拍攝路線與姿勢。行程包含橋梁、自行車街景與充滿生活感的河畔畫面。完成後提供精選照片，讓你帶走專屬城市記憶。', 'Magere Brug 橋頭', '阿姆斯特丹', 4.907400, 52.358300, '2026-07-21 19:30:58'),
(30, 4, 22, '阿姆斯特丹森林單車探索之旅', '騎著單車走進阿姆斯特丹森林，感受城市外圍的自然綠意。路線經過林間小徑、湖畔景觀與適合停留拍照的空間。導覽員會分享荷蘭人日常騎車與戶外休閒文化故事。適合喜歡輕度運動和自然風景的旅人。', 'Amsterdamse Bos 入口', '阿姆斯特丹', 4.839600, 52.325500, '2026-07-21 19:30:58'),
(31, 5, 26, '巴黎左岸晨光街拍漫遊之旅', '由攝影師帶你走入左岸晨光街景，捕捉自然互動與生活感畫面。沿途安排咖啡館與石板路取景，留下不刻意卻有故事的人像。提供簡單姿勢引導，第一次拍攝也能自在面對鏡頭。旅程結束後可獲得精選照片，收藏巴黎最溫柔的片刻。', 'Saint-Germain-des-Prés 地鐵站出口', '巴黎', 2.333300, 48.853400, '2026-07-21 20:14:21'),
(32, 3, 14, '法式市集私廚午宴品味體驗', '從早晨市集挑選當季食材，認識法國家庭料理重視的新鮮風味。跟著私廚完成前菜、主餐與甜點，學習實用的料理技巧。用餐時分享餐酒搭配與餐桌文化，感受道地生活節奏。適合想以味蕾深入認識巴黎的人，一起享受悠閒午宴。', 'Marché Bastille 市集入口', '巴黎', 2.369700, 48.853000, '2026-07-21 20:14:21'),
(33, 2, 8, '奧賽名畫故事藝術深度導覽', '從印象派代表作品出發，理解畫家如何用光線記錄巴黎的城市樣貌。導覽員會用容易理解的故事，帶你認識作品背後的人物與時代。避開艱深術語，讓第一次欣賞藝術也能找到自己的感動。行程保留自由觀賞時間，慢慢欣賞最喜歡的畫作。', 'Musée d\'Orsay 主入口前', '巴黎', 2.326600, 48.860000, '2026-07-21 20:14:21'),
(34, 1, 1, '泰晤士河畔古蹟漫步導覽之旅', '沿著泰晤士河步行，從經典地標認識倫敦不同時代留下的故事。導覽員會分享皇室、文學與城市發展的趣聞，讓街景不再只是照片背景。途中安排適合拍照的河岸角度，記錄旅程中的自然瞬間。適合第一次到倫敦，想快速掌握城市歷史脈絡的旅人。', 'Westminster 地鐵站 1 號出口', '倫敦', -0.127600, 51.500700, '2026-07-21 20:14:21'),
(35, 4, 19, '皇家公園單車綠意探索之旅', '騎著單車穿越倫敦皇家公園，從綠地與湖畔感受城市另一種悠閒節奏。路線平緩好騎，適合沒有單車經驗也想輕鬆探索的旅人。途中會停留隱藏花園與經典景點，兼顧拍照與休息時間。跟著在地帶領者前進，發現觀光地圖以外的清新風景。', 'Hyde Park Corner 地鐵站外', '倫敦', -0.159600, 51.503300, '2026-07-21 20:14:21'),
(36, 6, 31, '西區經典舞台劇夜遊體驗之旅', '夜幕降臨後走進西區街頭，感受劇院燈光與人群交織的熱鬧氛圍。帶領者會介紹經典劇院歷史，以及熱門音樂劇背後的小故事。演出前保留時間讓你挑選紀念品、拍照或品嚐附近小點。適合喜歡表演藝術，想體驗倫敦夜晚文化魅力的旅人。', 'Leicester Square 地鐵站出口', '倫敦', -0.128100, 51.511900, '2026-07-21 20:14:21'),
(37, 3, 15, '巴伐利亞家常料理手作體驗', '在溫暖的料理空間中學習巴伐利亞家庭常見菜色，感受樸實豐富的味道。從備料到擺盤都有主廚示範，讓每個步驟都能輕鬆跟上。完成後一起分享料理，認識當地人聚餐時重視的餐桌習慣。適合想離開觀光餐廳，親手體驗慕尼黑日常風味的旅人。', 'Viktualienmarkt 正門入口', '慕尼黑', 11.576100, 48.135100, '2026-07-21 20:14:21'),
(38, 2, 9, '慕尼黑宮廷藝術典藏導覽之旅', '走入昔日王室收藏空間，欣賞宮廷建築、人體藝術與珍貴裝飾作品。導覽員用生動故事介紹巴伐利亞王室，讓歷史人物更加貼近生活。行程安排重點展廳與拍照角度，避免在龐大館舍中迷失方向。適合喜歡藝術與歐洲歷史，希望深入認識慕尼黑文化的旅人。', 'Residenz München 售票處前', '慕尼黑', 11.577800, 48.141400, '2026-07-21 20:14:21'),
(39, 5, 27, '慕尼黑老城人像旅拍寫真體驗', '跟著在地攝影師走進老城廣場與彩色街角，拍下自然又有旅行感的人像。拍攝前會先了解你的穿搭與風格，安排最適合的取景路線。攝影師提供表情與動作引導，不必擔心面對鏡頭會尷尬。完成後取得精選成品，帶走一份有溫度的慕尼黑回憶。', 'Marienplatz 新市政廳前', '慕尼黑', 11.575500, 48.137400, '2026-07-21 20:14:21'),
(40, 1, 4, '運河金色年代歷史漫步導覽', '沿著運河與老宅漫步，認識阿姆斯特丹從貿易港口發展而來的歷史。導覽員會分享商人宅邸、倉庫與橋梁背後的城市生活故事。路線穿插較少遊客知道的巷弄，感受水都安靜而迷人的一面。適合想慢慢走讀城市，不只拍照打卡的文化旅行者。', 'Dam Square 國家紀念碑前', '阿姆斯特丹', 4.893600, 52.373100, '2026-07-21 20:14:21'),
(41, 4, 22, '風車村落單車田園探索之旅', '騎車前往運河旁的田園與風車村，感受阿姆斯特丹近郊開闊的風景。帶領者會安排平緩安全的路線，讓旅人能自在欣賞沿途景色。途中介紹乳酪、木鞋與水利文化，理解荷蘭人如何與水共存。適合喜歡戶外活動，也想拍下明亮鄉村畫面的旅人。', 'Amsterdam Centraal 車站前廣場', '阿姆斯特丹', 4.900300, 52.379100, '2026-07-21 20:14:21'),
(42, 6, 34, '城市秘境爵士夜生活體驗之旅', '傍晚走入運河旁的特色酒吧與爵士空間，感受城市夜晚的自在節奏。帶領者會介紹不同音樂場地的故事，找到旅人較少知道的演出角落。行程包含一杯在地飲品，讓你自然融入阿姆斯特丹夜生活。適合喜歡音樂、社交與輕鬆氛圍的成年旅人參加。', 'Leidseplein 廣場中央', '阿姆斯特丹', 4.881000, 52.364700, '2026-07-21 20:14:21'),
(43, 2, 11, '威尼斯面具工坊藝術導覽體驗', '走進傳統面具工坊，認識威尼斯嘉年華面具的色彩、工法與象徵意義。職人會示範手工裝飾細節，讓你看見精緻作品背後需要的耐心。導覽過程分享面具在戲劇與社交文化中的重要角色。適合喜歡手作藝術，也想認識水都另一面歷史的旅人。', 'Campo Santo Stefano 廣場中央', '威尼斯', 12.327900, 45.431300, '2026-07-21 20:14:21'),
(44, 3, 17, '潟湖海鮮市集風味品嚐體驗', '跟著在地嚮導走訪早晨市場，認識潟湖漁獲與威尼斯家庭料理的特色。品嚐新鮮海鮮小點與地方酒飲，感受不同於觀光餐廳的真實風味。帶領者會分享食材季節與點餐技巧，讓你之後也能自在探索。適合喜歡美食與市場文化，希望用味蕾旅行的旅人。', 'Rialto Market 市集入口', '威尼斯', 12.336000, 45.439000, '2026-07-21 20:14:21'),
(45, 5, 29, '水都晨霧人像旅拍寫真之旅', '清晨走進光線柔和的運河街景，避開人潮拍下最有水都氣氛的人像照片。攝影師會依照你的風格安排橋梁、小船與巷弄作為拍攝背景。過程提供自然動作引導，讓照片保有旅行中的真實情緒。適合情侶、好友或獨旅者，留下獨一無二的威尼斯紀念。', 'Ponte dell\'Accademia 橋頭', '威尼斯', 12.328800, 45.430800, '2026-07-21 20:14:21'),
(46, 1, 5, '總督宮秘史古蹟深度導覽之旅', '走進總督宮華麗廳堂與隱密走道，認識威尼斯共和國昔日的權力核心。導覽員會用人物故事解說政治、藝術與法律如何交織在同一座建築。除了經典景點，也帶你留意容易忽略的壁畫與建築細節。適合想深入理解威尼斯歷史，而非只匆匆參觀的旅人。', 'Doge\'s Palace 售票處前', '威尼斯', 12.340000, 45.433700, '2026-07-21 20:14:21'),
(47, 4, 24, '海岸步道夕陽健行探索之旅', '沿著海岸步道前進，從高處欣賞地中海海風、城市天際線與夕陽變化。路線難度適中，途中安排休息點讓大家能拍照與補充體力。嚮導會分享當地自然地形與居民生活，讓健行不只是走路。適合喜歡戶外景色，也想遠離市中心人潮的旅人參加。', 'Barceloneta 海灘鐘塔前', '巴塞隆納', 2.193500, 41.376300, '2026-07-21 20:14:21'),
(48, 6, 36, '加泰隆尼亞燈光夜生活體驗', '從熱鬧廣場出發探索夜晚街區，感受加泰隆尼亞城市獨有的活力與節奏。帶領者會介紹特色酒吧、音樂空間與適合拍照的燈光街景。行程保留自由交流時間，讓旅人能用自己的步調享受夜晚。適合成年旅客參加，喜歡社交、音樂與城市夜色的人。', 'Plaça de Catalunya 廣場中央', '巴塞隆納', 2.170100, 41.387000, '2026-07-21 20:14:21'),
(49, 2, 12, '畢卡索足跡藝術故事導覽之旅', '循著畢卡索早年在巴塞隆納留下的足跡，認識他如何受到城市文化啟發。導覽員會連結街區、藝術學院與作品故事，讓畫家的成長歷程更立體。行程以輕鬆方式介紹現代藝術，不需要任何專業背景也能理解。適合想從城市街景走進藝術世界的旅人參加。', 'Museu Picasso Barcelona 門口', '巴塞隆納', 2.181600, 41.385100, '2026-07-21 20:14:21'),
(50, 3, 18, '地中海市場料理手作體驗之旅', '從市場採買新鮮蔬果與海鮮，認識地中海料理重視簡單食材的美味。跟著主廚完成多道家常菜，學習橄欖油、香料與火候的搭配方式。用餐時分享巴塞隆納飲食文化，感受熱情自在的餐桌氣氛。適合想親手做菜，也想深入了解當地生活的美食旅人。', 'Mercat de la Boqueria 正門', '巴塞隆納', 2.172300, 41.382600, '2026-07-21 20:14:21'),
(51, 1, 1, '皇家衛兵儀式深度導覽體驗', '從白金漢宮周邊出發，認識衛兵交接儀式的歷史背景與觀看重點。帶你走訪王室地標並分享最佳拍攝角度。以輕鬆節奏了解倫敦的王室文化。適合第一次造訪倫敦的旅人。', 'Buckingham Palace 正門前', '倫敦', -0.141890, 51.501364, '2026-07-23 09:25:43'),
(52, 4, 19, '泰晤士河畔夜景攝影散步之旅', '沿著泰晤士河畔展開黃昏散步，欣賞倫敦眼與大笨鐘逐漸亮起的夜景。帶領你尋找適合拍照的河岸視角。途中會分享城市地標背後的小故事。適合喜歡夜景與慢旅行的人。', 'Westminster Bridge 北端', '倫敦', -0.121819, 51.500729, '2026-07-23 09:25:43'),
(53, 5, 25, '攝政公園晨光人像攝影體驗', '在柔和晨光中於攝政公園進行自然風格人像拍攝。攝影師會協助引導姿勢與表情，讓畫面看起來更放鬆自然。行程會結合草地、湖畔與樹蔭場景。留下專屬於倫敦旅行的照片記憶。', 'Regent\'s Park 南門', '倫敦', -0.152778, 51.531270, '2026-07-23 09:25:43'),
(54, 6, 31, '西區歌劇魅影夜晚觀賞體驗', '走進倫敦西區劇院，欣賞經典音樂劇的舞台魅力與現場演出能量。行前會介紹劇院文化與觀賞禮儀。演出後可在周邊街區散步感受夜晚氛圍。適合想體驗倫敦娛樂文化的旅人。', 'His Majesty\'s Theatre 門口', '倫敦', -0.131705, 51.509439, '2026-07-23 09:25:43'),
(55, 2, 8, '羅浮宮人體藝術深度導覽之旅', '由導覽員帶領認識羅浮宮的重要館藏與人體藝術發展脈絡。避開容易迷路的動線，將有限時間放在最值得看的作品。途中會分享畫作背後的故事與時代背景。適合想深入理解藝術而非只打卡的旅人。', 'Musée du Louvre 金字塔前', '巴黎', 2.336443, 48.860611, '2026-07-23 09:25:43'),
(56, 3, 14, '左岸私廚法式晚餐品味之夜', '在巴黎左岸的私廚空間品嘗以當季食材設計的法式料理。主廚會介紹料理靈感與搭配方式，讓用餐不只是吃一頓飯。餐桌氣氛輕鬆並可與其他旅人交流。適合喜歡美食與生活感體驗的人。', 'Saint-Germain-des-Prés 附近', '巴黎', 2.333333, 48.854722, '2026-07-23 09:25:43'),
(57, 5, 26, '塞納河畔黃昏人像旅拍體驗', '在塞納河畔與巴黎街角進行黃昏人像拍攝，捕捉城市最柔和的光線。攝影師會協助規劃拍攝路線與自然互動姿勢。畫面將結合橋梁、河景與經典建築。適合情侶、朋友或獨旅紀念。', 'Pont Alexandre III 橋旁', '巴黎', 2.313644, 48.863796, '2026-07-23 09:25:43'),
(58, 1, 2, '聖心堂街區故事漫步導覽體驗', '從蒙馬特山腳慢慢步行至聖心堂，認識藝術家與街頭文化留下的痕跡。導覽員會分享街區轉角的小故事與私房視角。沿途可欣賞巴黎市景與特色店家。適合喜歡歷史與散步節奏的旅人。', 'Anvers 地鐵站出口', '巴黎', 2.344720, 48.882117, '2026-07-23 09:25:43'),
(59, 2, 9, '現代藝術館策展深度導覽體驗', '走進慕尼黑現代藝術館，從策展角度理解作品之間的關聯與時代脈絡。導覽會用容易理解的方式拆解抽象藝術概念。途中保留時間讓你提問與交流觀察。適合對當代藝術感到好奇的旅人。', 'Pinakothek der Moderne 門口', '慕尼黑', 11.574724, 48.147755, '2026-07-23 09:25:43'),
(60, 3, 15, '巴伐利亞家常料理手作體驗', '在溫暖的料理空間學習製作巴伐利亞家庭常見菜色與點心。從備料、調味到擺盤都會親自參與，完成後一起享用成果。主廚也會分享德國飲食文化與採買技巧。適合喜歡動手做料理的旅人。', 'Viktualienmarkt 正門入口', '慕尼黑', 11.576124, 48.135125, '2026-07-23 09:25:43'),
(61, 6, 33, '傳統啤酒館現場音樂之夜體驗', '走進具有在地氣氛的傳統啤酒館，感受現場音樂與慕尼黑夜生活文化。行程包含認識不同啤酒風味與基本飲用禮儀。也會介紹啤酒節背後的歷史由來。適合想融入當地熱鬧氛圍的旅人。', 'Hofbräuhaus München 門口', '慕尼黑', 11.580437, 48.137430, '2026-07-23 09:25:43'),
(62, 2, 10, '梵谷博物館名作深度導覽之旅', '透過精選館藏認識梵谷不同時期的創作轉變與人生故事。導覽員會說明色彩、筆觸與構圖背後想傳達的情感。避開走馬看花的參觀方式，專注理解幾件代表作品。適合喜歡藝術與人物故事的旅人。', 'Van Gogh Museum 主入口', '阿姆斯特丹', 4.881094, 52.358416, '2026-07-23 09:25:43'),
(63, 4, 22, '運河單車晨光探索漫遊體驗', '騎著單車穿梭阿姆斯特丹運河與安靜街區，感受城市剛甦醒的節奏。路線會避開最擁擠的觀光區，保留更多在地生活畫面。途中停靠幾個適合拍照與休息的角落。適合喜歡自由探索與戶外活動的旅人。', 'Amsterdam Centraal Station 前廣場', '阿姆斯特丹', 4.900272, 52.379189, '2026-07-23 09:25:43'),
(64, 6, 34, '運河酒吧現場爵士微醺之夜', '在運河旁的特色酒吧聆聽現場爵士樂，感受阿姆斯特丹夜晚悠閒又有活力的氣氛。行程會介紹酒吧文化與推薦飲品風格。可與同行旅人自在聊天交流。適合喜歡音樂、夜景與慢節奏社交的人。', 'Leidseplein 廣場旁', '阿姆斯特丹', 4.881076, 52.363878, '2026-07-23 09:25:43'),
(65, 1, 5, '總督宮歷史秘聞深度導覽之旅', '走進總督宮認識威尼斯共和國的政治制度、藝術裝飾與權力故事。導覽員會帶你留意一般參觀容易忽略的建築細節。透過宮殿空間理解城市昔日的海洋霸權。適合喜歡歷史、建築與故事性導覽的旅人。', 'Palazzo Ducale 正門前', '威尼斯', 12.340432, 45.433666, '2026-07-23 09:25:43'),
(66, 2, 11, '威尼斯雙年展藝術路線導覽體驗', '沿著雙年展周邊展館與街區探索當代藝術如何走進威尼斯日常。導覽員會挑選易理解的作品，分享創作概念與觀展方法。行程兼顧藝術內容與城市散步樂趣。適合第一次接觸雙年展的旅人。', 'Giardini della Biennale 入口', '威尼斯', 12.360230, 45.430107, '2026-07-23 09:25:43'),
(67, 4, 23, '潟湖日落划船自然探索體驗', '在專業帶領下於威尼斯潟湖划船，從水面欣賞遠離人潮的島嶼與天際線。行程會配合日落時段，感受光線在水面變化的美景。途中分享潟湖生態與城市水路故事。適合喜歡自然與安靜戶外體驗的旅人。', 'Fondamente Nove 碼頭', '威尼斯', 12.342140, 45.445140, '2026-07-23 09:25:43'),
(68, 1, 6, '聖家堂建築細節深度導覽體驗', '從聖家堂外觀到內部光影，認識高第如何把自然元素融入建築設計。導覽員會解說立面雕刻、柱體與彩色玻璃的象徵意義。讓你不只拍照，也能理解這座建築的獨特語言。適合喜歡設計與建築故事的旅人。', 'Sagrada Família 主入口前', '巴塞隆納', 2.174355, 41.403629, '2026-07-23 09:25:43'),
