((SELECT `id` FROM `posts` WHERE `slug` = 'official-venice-category-5-2'), 48, '利用倒影和背影取景的方式很適合威尼斯，比每張照片都正面看鏡頭自然多了。', DATE_ADD((SELECT `published_at` FROM `posts` WHERE `slug` = 'official-venice-category-5-2'), INTERVAL 6 HOUR)),
