INSERT INTO `experience_reviews` (`id`, `order_item_id`, `experience_id`, `member_id`, `rating`, `comment`, `created_at`, `image_url`) VALUES
(1, 253, 1, 18, 5, '剛開始時，我就注意到鏡頭前慢慢放鬆的過程，讓我很快進入當下。帶領者講解得很生活化，不會讓人覺得資訊太多。我覺得花在這裡的時間很值得。', '2026-06-16 12:00:00', NULL),
(2, 353, 1, 29, 5, '走到一半時，我特別喜歡光線剛好落下的位置，讓我很快進入當下。中間留有足夠空間，想多看一點或稍微休息都很自在。如果朋友問起，我會願意分享這個經驗。', '2026-06-17 12:00:00', NULL),
(3, 453, 1, 40, 5, '回頭整理照片時，我還記得等待快門時的小互動，讓我很快進入當下。同行的人節奏不完全一樣，現場還是照顧得很平均。同行朋友都說下次還想找類似的安排。', '2026-06-18 12:00:00', NULL),
(4, 553, 1, 51, 5, '和同行朋友聊天時，大家都提到看到預覽照片時的驚喜，讓我很快進入當下。遇到提問時回應得很實在，讓人不怕問問題。這份自在感，是我最想帶走的部分。', '2026-06-19 12:00:00', NULL),
(5, 653, 1, 2, 5, '原本只是隨意看看，卻因為走路時自然留下的瞬間，讓我很快進入當下。過程不會一直被催著走，整體很放鬆。比自己匆匆查資料再走過，收穫更多。', '2026-06-16 12:00:00', NULL),
(6, 753, 1, 13, 5, '讓我最想停下來感受的，是街景與人物合在一起的感覺，讓我很快進入當下。現場有變化時調整得很順，不會讓人手忙腳亂。這是那種不需特別包裝，也會被記住的體驗。', '2026-06-17 12:00:00', NULL),
(7, 853, 1, 24, 5, '結束前回想起來，最有畫面的還是拍攝之間聊天的節奏，讓我很快進入當下。有些細節若不是有人提醒，大概很容易錯過。它讓原本普通的一天多了一點層次。', '2026-06-18 12:00:00', NULL),
(8, 953, 1, 35, 5, '旅途中讓我放慢腳步的，是換個角度後的畫面，讓我很快進入當下。內容有深度卻不難懂，第一次接觸也能跟上。它讓這趟旅行多了一段可以慢慢回想的片段。', '2026-06-19 12:00:00', NULL),
(9, 1103, 1, 46, 5, '沒有刻意安排驚喜，但我仍記住了原本尷尬的表情變自然的時候，讓我很快進入當下。整體安排很順，結束後不會覺得累得太過頭。離開後還一直維持著很舒服的心情。', '2026-07-06 12:00:00', NULL),
(10, 1203, 1, 57, 5, '這趟裡最舒服的一個片刻，是不經意回頭的那個瞬間，讓我很快進入當下。回程時大家還在交換剛剛注意到的小事。我很喜歡這種不被催促的節奏。', '2026-06-17 12:00:00', NULL),
(11, 254, 2, 8, 5, '剛開始時，我就注意到作品旁邊的光線，讓我很快進入當下。帶領者講解得很生活化，不會讓人覺得資訊太多。我覺得花在這裡的時間很值得。', '2026-06-18 12:00:00', NULL),
(12, 354, 2, 19, 5, '走到一半時，我特別喜歡建築空間的轉換，讓我很快進入當下。中間留有足夠空間，想多看一點或稍微休息都很自在。如果朋友問起，我會願意分享這個經驗。', '2026-06-19 12:00:00', NULL),
(13, 454, 2, 30, 5, '回頭整理照片時，我還記得展牆上的安排，讓我很快進入當下。同行的人節奏不完全一樣，現場還是照顧得很平均。同行朋友都說下次還想找類似的安排。', '2026-06-16 12:00:00', NULL),
(14, 554, 2, 41, 5, '和同行朋友聊天時，大家都提到展間裡的留白，讓我很快進入當下。遇到提問時回應得很實在，讓人不怕問問題。這份自在感，是我最想帶走的部分。', '2026-06-17 12:00:00', NULL),
(15, 654, 2, 52, 5, '原本只是隨意看看，卻因為不同作品之間的呼應，讓我很快進入當下。過程不會一直被催著走，整體很放鬆。比自己匆匆查資料再走過，收穫更多。', '2026-06-18 12:00:00', NULL),
(16, 754, 2, 3, 5, '讓我最想停下來感受的，是作品背後的小線索，讓我很快進入當下。現場有變化時調整得很順，不會讓人手忙腳亂。這是那種不需特別包裝，也會被記住的體驗。', '2026-06-19 12:00:00', NULL),
(17, 854, 2, 14, 5, '結束前回想起來，最有畫面的還是一幅畫停下來後的感受，讓我很快進入當下。有些細節若不是有人提醒，大概很容易錯過。它讓原本普通的一天多了一點層次。', '2026-06-16 12:00:00', NULL),
(18, 954, 2, 25, 5, '旅途中讓我放慢腳步的，是畫面中不起眼的細節，讓我很快進入當下。內容有深度卻不難懂，第一次接觸也能跟上。它讓這趟旅行多了一段可以慢慢回想的片段。', '2026-06-17 12:00:00', NULL),
(19, 1104, 2, 36, 5, '沒有刻意安排驚喜，但我仍記住了顏色在近看時的層次，讓我很快進入當下。整體安排很順，結束後不會覺得累得太過頭。離開後還一直維持著很舒服的心情。', '2026-07-09 12:00:00', NULL),
(20, 1204, 2, 47, 5, '這趟裡最舒服的一個片刻，是雕塑周圍的空間感，讓我很快進入當下。回程時大家還在交換剛剛注意到的小事。我很喜歡這種不被催促的節奏。', '2026-06-20 12:00:00', NULL),
(21, 255, 3, 58, 5, '剛開始時，我就注意到餐桌上剛端出的熱氣，讓我很快進入當下。帶領者講解得很生活化，不會讓人覺得資訊太多。我覺得花在這裡的時間很值得。', '2026-06-16 12:00:00', NULL),
(22, 355, 3, 9, 5, '走到一半時，我特別喜歡點餐時聽到的小建議，讓我很快進入當下。中間留有足夠空間，想多看一點或稍微休息都很自在。如果朋友問起，我會願意分享這個經驗。', '2026-06-17 12:00:00', NULL),
(23, 455, 3, 20, 5, '回頭整理照片時，我還記得用餐時周圍的聊天聲，讓我很快進入當下。同行的人節奏不完全一樣，現場還是照顧得很平均。同行朋友都說下次還想找類似的安排。', '2026-06-18 12:00:00', NULL),
(24, 555, 3, 31, 5, '和同行朋友聊天時，大家都提到小店裡傳來的香氣，讓我很快進入當下。遇到提問時回應得很實在，讓人不怕問問題。這份自在感，是我最想帶走的部分。', '2026-06-19 12:00:00', NULL),
(25, 655, 3, 42, 5, '原本只是隨意看看，卻因為店家招呼客人的方式，讓我很快進入當下。過程不會一直被催著走，整體很放鬆。比自己匆匆查資料再走過，收穫更多。', '2026-06-16 12:00:00', NULL),
(26, 755, 3, 53, 5, '讓我最想停下來感受的，是巷口那家不起眼的小店，讓我很快進入當下。現場有變化時調整得很順，不會讓人手忙腳亂。這是那種不需特別包裝，也會被記住的體驗。', '2026-06-17 12:00:00', NULL),
(27, 855, 3, 4, 5, '結束前回想起來，最有畫面的還是第一口入口的味道，讓我很快進入當下。有些細節若不是有人提醒，大概很容易錯過。它讓原本普通的一天多了一點層次。', '2026-06-18 12:00:00', NULL),
(28, 955, 3, 15, 5, '旅途中讓我放慢腳步的，是食材搭配出的層次，讓我很快進入當下。內容有深度卻不難懂，第一次接觸也能跟上。它讓這趟旅行多了一段可以慢慢回想的片段。', '2026-06-19 12:00:00', NULL),
(29, 1105, 3, 26, 5, '沒有刻意安排驚喜，但我仍記住了醬料和主食的搭配，讓我很快進入當下。整體安排很順，結束後不會覺得累得太過頭。離開後還一直維持著很舒服的心情。', '2026-07-08 12:00:00', NULL),
(30, 1205, 3, 37, 5, '這趟裡最舒服的一個片刻，是甜點收尾時的驚喜，讓我很快進入當下。回程時大家還在交換剛剛注意到的小事。我很喜歡這種不被催促的節奏。', '2026-06-19 12:00:00', NULL),
(31, 256, 4, 48, 5, '剛開始時，我就注意到樹影落在路面的樣子，讓我很快進入當下。帶領者講解得很生活化，不會讓人覺得資訊太多。我覺得花在這裡的時間很值得。', '2026-06-18 12:00:00', NULL),
